            let tmp3 = (FStarC_Format.fmt1 "Pattern (%s) contains illegal symbols; dropping it" tmp2) in
            (FStarC_Errors.fStarC_Errors_log_issue__range_string r FStarC_Errors_Codes.Warning_SMTPatternIllFormed tmp3);
            [])
        )))) in
      (if (match vars with
        | [] -> true
        | tmp1 -> false
      ) then body else (match body with
        | (App (TrueOp, tmp1, tmp2)) -> body
        | tmp1 -> (let tmp2 = (all_pats_ok pats) in
          (Quant (qop, tmp2, wopt, vars, body, r)))
