let rec abstr__aux (index_of : (fv -> (Prims.int) option)) (ix : Prims.int) (t : term) : term =
  (match t with
    | (Integer (tmp)) -> t
    | (String (tmp)) -> t
    | (Real (tmp)) -> t
    | (BoundV (tmp)) -> t
    | (FreeV (x)) -> (let tmp = (index_of x) in
      (match tmp with
        | None -> t
        | (Some (i)) -> (mkBoundV (Prims.op_Plus i ix))
